function ItemGallery({ item, className = "h-52" }) {
  const photos = item.fotos && item.fotos.length > 0 ? item.fotos : (item.foto ? [item.foto] : []);
  const [activeIndex, setActiveIndex] = useState(0);
  const scrollerRef = useRef(null);

  if (photos.length <= 1) {
    return <ItemImage kategori={item.kategori} foto={photos[0]} className={className} />;
  }

  function handleScroll() {
    const el = scrollerRef.current;
    if (!el) return;
    const idx = Math.round(el.scrollLeft / el.clientWidth);
    setActiveIndex(idx);
  }

  return (
    <div className={`relative w-full ${className} rounded-2xl overflow-hidden`}>
      <div
        ref={scrollerRef}
        onScroll={handleScroll}
        className="w-full h-full flex overflow-x-auto no-scrollbar"
        style={{ scrollSnapType: "x mandatory" }}
      >
        {photos.map((src, i) => (
          <div key={i} className="w-full h-full shrink-0" style={{ scrollSnapAlign: "center" }}>
            <img src={src} alt={`${item.nama} ${i + 1}`} className="w-full h-full object-cover" />
          </div>
        ))}
      </div>
      <div className="absolute bottom-2.5 left-0 right-0 flex items-center justify-center gap-1.5">
        {photos.map((_, i) => (
          <span
            key={i}
            className="rounded-full transition-all"
            style={{
              width: i === activeIndex ? 14 : 5,
              height: 5,
              background: i === activeIndex ? "#fff" : "rgba(255,255,255,0.5)",
            }}
          />
        ))}
      </div>
      <span className="absolute top-2.5 right-2.5 px-2 py-0.5 rounded-full fsz-10p5 font-bold" style={{ background: "rgba(0,0,0,0.55)", color: "#fff" }}>
        {activeIndex + 1}/{photos.length}
      </span>
    </div>
  );
}

