  function EditProfilePage() {
    const [nama, setNama] = useState(userProfile.nama);
    const [email, setEmail] = useState(userProfile.email);
    const [photo, setPhoto] = useState(userProfile.photo);
    const [photoFile, setPhotoFile] = useState(null);
    const [lokasi, setLokasi] = useState(userLokasi);
    const [lokasiLat, setLokasiLat] = useState(userLat);
    const [lokasiLng, setLokasiLng] = useState(userLng);
    const [showLokasiPicker, setShowLokasiPicker] = useState(false);
    const [saving, setSaving] = useState(false);
    const fileInputRef = useRef(null);

    function handlePhoto(e) {
      const file = e.target.files?.[0];
      if (file) {
        setPhotoFile(file);
        const reader = new FileReader();
        reader.onload = () => setPhoto(reader.result);
        reader.readAsDataURL(file);
      }
    }

    async function save() {
      if (!session) return;
      setSaving(true);
      try {
        let photoUrl = userProfile.photo;
        if (photoFile) {
          const ext = photoFile.name.split(".").pop() || "jpg";
          const path = `${session.user.id}/${Date.now()}.${ext}`;
          const { error: upErr } = await supabase.storage
            .from("profile-photos")
            .upload(path, photoFile, { contentType: photoFile.type || "image/jpeg" });
          if (upErr) throw upErr;
          const { data: urlData } = supabase.storage.from("profile-photos").getPublicUrl(path);
          photoUrl = urlData.publicUrl;
        }

        const finalNama = nama.trim() || userProfile.nama;
        const finalEmail = email.trim() || userProfile.email;

        const { error: updErr } = await supabase
          .from("profiles")
          .update({ nama: finalNama, email: finalEmail, photo_url: photoUrl, lokasi_utama: lokasi, lat: lokasiLat, lng: lokasiLng })
          .eq("id", session.user.id);
        if (updErr) throw updErr;

        setUserProfile({ nama: finalNama, email: finalEmail, photo: photoUrl });
        setUserLokasi(lokasi);
        if (lokasiLat && lokasiLng) { setUserLat(lokasiLat); setUserLng(lokasiLng); }
        goBack();
        showToast("Profil berhasil diperbarui");
      } catch (err) {
        console.error("Gagal simpan profil:", err);
        showToast(`Gagal menyimpan profil: ${err.message || "coba lagi."}`);
      } finally {
        setSaving(false);
      }
    }

    return (
      <div className="h-full w-full flex flex-col" style={{ background: C.bg }}>
        <StatusBar />
        <Header title="Edit Profil" onBack={goBack} />
        <div className="flex-1 overflow-y-auto px-5 pb-8">
          <div className="flex flex-col items-center mb-6">
            <input ref={fileInputRef} type="file" accept="image/*" onChange={handlePhoto} className="hidden" />
            <button onClick={() => fileInputRef.current?.click()} className="relative w-24 h-24 rounded-full flex items-center justify-center font-display font-extrabold fsz-18 text-white overflow-hidden transition active:scale-95" style={{ background: C.navy }}>
              {photo ? <img src={photo} alt={nama} className="w-full h-full object-cover" /> : (nama[0] || "?")}
              <div className="absolute bottom-0 right-0 w-8 h-8 rounded-full flex items-center justify-center" style={{ background: C.tosca, border: "2.5px solid #fff" }}>
                <Camera size={14} color="#fff" />
              </div>
            </button>
            <span className="fsz-11p5 tc-gray font-semibold mt-2">Ubah foto profil</span>
          </div>

          <label className="fsz-12 font-bold tc-slate mb-1.5 block">Nama Lengkap</label>
          <input value={nama} onChange={(e) => setNama(e.target.value)} placeholder="Nama kamu" className="w-full rounded-2xl px-4 py-3.5 outline-none fsz-14 font-medium mb-4" style={{ background: C.gray, color: C.text }} />

          <label className="fsz-12 font-bold tc-slate mb-1.5 block">Email</label>
          <input value={email} onChange={(e) => setEmail(e.target.value)} placeholder="nama@email.com" type="email" className="w-full rounded-2xl px-4 py-3.5 outline-none fsz-14 font-medium mb-4" style={{ background: C.gray, color: C.text }} />

          <label className="fsz-12 font-bold tc-slate mb-1.5 block">Lokasi Utama</label>
          <button onClick={() => setShowLokasiPicker(true)} className="w-full flex items-center gap-2 rounded-2xl px-4 py-3.5 mb-6 transition active:scale-95" style={{ background: C.gray }}>
            <MapPin size={16} color={C.tosca} />
            <span className="fsz-13p5 font-semibold flex-1 text-left" style={{ color: C.text }}>{lokasi}</span>
            <ChevronRight size={16} color="#94A3B8" />
          </button>

          <PrimaryButton onClick={save} icon={Check} disabled={saving}>{saving ? "Menyimpan..." : "Simpan Perubahan"}</PrimaryButton>
        </div>
        {showLokasiPicker && (
          <LocationPickerSheet
            value={lokasi}
            initialLat={lokasiLat}
            initialLng={lokasiLng}
            onSelect={(v, lat, lng) => { setLokasi(v); if (lat && lng) { setLokasiLat(lat); setLokasiLng(lng); } setShowLokasiPicker(false); }}
            onClose={() => setShowLokasiPicker(false)}
            title="Ubah Lokasi Utama"
          />
        )}
      </div>
    );
  }

